import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),r={name:"changelog.md"};function n(d,e,c,s,l,g){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to the Geomilli monorepo will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h3 id="component-tags" tabindex="-1">Component Tags <a class="header-anchor" href="#component-tags" aria-label="Permalink to &quot;Component Tags&quot;">​</a></h3><p>Every changelog entry must be prefixed with one of the following component tags indicating the affected subproject:</p><ul><li><strong>api</strong>: Search &amp; Geo REST API service (<code>geomilli-api/</code>)</li><li><strong>mcp</strong>: Model Context Protocol adapter service (<code>geomilli-mcp/</code>)</li><li><strong>harvester</strong>: Streaming OSM ingestion and enrichment engine (<code>geomilli-harvester/</code>)</li><li><strong>studio</strong>: Developer console and MapLibre GL playground (<code>geomilli-studio/</code>)</li><li><strong>docs</strong>: Documentation site and API specifications (<code>docs/</code>)</li><li><strong>infra</strong>: Root orchestration, CI/CD workflows, Docker Compose, and build scripts</li></ul><h3 id="governance-for-contributors-agents" tabindex="-1">Governance for Contributors &amp; Agents <a class="header-anchor" href="#governance-for-contributors-agents" aria-label="Permalink to &quot;Governance for Contributors &amp; Agents&quot;">​</a></h3><p>Whenever making user-visible, functional, architectural, or breaking changes, contributors and AI agents <strong>must append</strong> a concise entry under the <code>## [Unreleased]</code> section with the appropriate component tag. Releases promote <code>[Unreleased]</code> entries to a versioned release header.</p><hr><h2 id="unreleased" tabindex="-1"><a href="https://github.com/geomilli/geomilli/compare/v1.0.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>mcp</strong>: Complete MCP tool catalog (13 Tier-1 tools + 3 gated ops tools) in <code>geomilli-mcp</code>: <ul><li>Geocoding: <code>geocode</code>, <code>reverse_geocode</code></li><li>Discovery: <code>search_places</code>, <code>find_nearby</code>, <code>places_in_area</code>, <code>get_place</code></li><li>Aviation: <code>find_airports</code>, <code>get_airport</code></li><li>Admin Hierarchy: <code>list_countries</code>, <code>list_regions</code>, <code>list_cities</code></li><li>Reference: <code>list_place_categories</code>, <code>measure_distance</code></li><li>Operations (gated): <code>get_service_status</code>, <code>list_import_queue</code>, <code>list_importable_countries</code></li></ul></li><li><strong>mcp</strong>: MCP resources for <code>geomilli://taxonomy</code>, <code>geomilli://languages</code>, <code>geomilli://countries</code>, <code>geomilli://schema/place</code>, and <code>geomilli://places/{id}</code> URI template.</li><li><strong>mcp</strong>: MCP workflow prompt templates: <code>explore_area</code>, <code>describe_location</code>, and <code>plan_airport_transfer</code>.</li><li><strong>mcp</strong>: Initial MCP server skeleton (<code>geomilli-mcp</code>) supporting stdio and Streamable HTTP transports with Bearer auth, Origin allowlisting, taxonomy caching, and reference tool <code>list_countries</code> (RFC-001).</li><li><strong>api</strong>: Added dynamic <code>/v1/openapi.json</code> handler serving runtime OpenAPI 3.1 specification with active build version from <code>internal/version.Version</code>.</li><li><strong>api</strong>: Added automated route coverage and synchronization test suite <code>openapi_routes_test.go</code> ensuring router routes, OpenAPI spec, and docs copy stay synchronized.</li><li><strong>infra</strong>: Changelog governance policy, PR template, and CI guard workflow enforcing changelog updates on code changes.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>api</strong>: ⚠️ BREAKING: Standardize API error responses to the <code>{&quot;error&quot;:{&quot;code&quot;:&quot;...&quot;,&quot;message&quot;:&quot;...&quot;,&quot;status&quot;:...}}</code> envelope (RFC-001 §11.2).</li><li><strong>api</strong>: Meilisearch search and entity query failures now return HTTP 502 <code>upstream_unavailable</code> instead of generic HTTP 500 errors.</li><li><strong>api</strong>: Enforce a maximum radius cap of 100,000 meters (100 km) on <code>/v1/reverse</code> and echo effective <code>radius_meters</code> across spatial responses.</li><li><strong>api</strong>: Query parameters (<code>lat</code>, <code>lng</code>, <code>radius_meters</code>, <code>limit</code>, <code>offset</code>) now use unified parser utilities with automatic clamping to defined ranges.</li><li><strong>api</strong>: Service version is now injected dynamically at build time via <code>-ldflags</code> from <code>VERSION</code> (defaults to &quot;dev&quot;).</li><li><strong>studio</strong>: Error handling across Playground, Importer, and LanguageManager updated to parse the RFC-001 error envelope with graceful legacy fallback.</li><li><strong>docs</strong>: Reconciled API documentation (<code>overview.md</code>, <code>autocomplete-and-search.md</code>, <code>geospatial-apis.md</code>) with actual Go handler implementations, updating response envelopes (<code>took_ms</code>, <code>total_hits</code>, <code>facets</code>, <code>results</code>), parameter names (<code>radius_meters</code>), limits, and error envelopes.</li><li><strong>docs</strong>: Removed non-existent <code>API_AUTH_TOKEN</code> authentication documentation in favor of network edge proxy guidelines.</li><li><strong>docs</strong>: Created canonical OpenAPI 3.1 specification at <code>geomilli-api/api/openapi.yaml</code> documenting all 27 Chi router routes, synced byte-for-byte to <code>docs/api/openapi.yaml</code>.</li></ul><h2 id="_1-0-0-2026-10-24" tabindex="-1"><a href="https://github.com/geomilli/geomilli/releases/tag/v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2026-10-24 <a class="header-anchor" href="#_1-0-0-2026-10-24" aria-label="Permalink to &quot;[1.0.0] - 2026-10-24&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>api</strong>: High-throughput geospatial query engine with <code>/autocomplete</code>, <code>/search</code>, <code>/reverse</code>, <code>/nearby</code>, <code>/bbox</code>, <code>/airports</code>, <code>/countries</code>, and <code>/taxonomy</code> routes.</li><li><strong>harvester</strong>: Streaming OpenStreetMap PBF ingestion daemon with <code>osmium-tool</code> filtering, SQLite WAL caching, and Wikidata/Wikipedia pageviews enrichment.</li><li><strong>studio</strong>: Interactive developer console with MapLibre GL map playground, real-time importer telemetry, and language management.</li><li><strong>docs</strong>: VitePress developer documentation site covering architecture, ingestion pipeline, API references, and quickstarts.</li><li><strong>docs</strong>: Add GitHub Pages deployment links, Geomilli Studio showcase screenshots, and reorder README for API-first architecture with explicit scaling limits.</li><li><strong>infra</strong>: Multi-service Docker Compose orchestration and Make targets (<code>make up</code>, <code>make down</code>, <code>make build</code>, <code>make test</code>).</li><li><strong>infra</strong>: GitHub Actions CI test matrix, automated GitHub Pages deployment for documentation, and CodeQL security analysis.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>api</strong>: Ensure deterministic tie-breaking in <code>topNQueries</code> and verify query membership in telemetry tests.</li><li><strong>infra</strong>: Resolve GitHub Actions runner race condition and upgrade Chi router to v5.3.0 to address upstream security vulnerabilities.</li></ul>',19)])])}const m=o(r,[["render",n]]);export{u as __pageData,m as default};
